import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR (Zdna ghir l-logic dyal n-choufo user connecte) ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const isActive = (path) => location.pathname === path;

  // N-cheddou smiya li khbbina f storage mlli dar login
  const user = localStorage.getItem('username');

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[
            { name: 'Accueil', path: '/' },
            { name: 'Menu', path: '/menu' },
            { name: 'À Propos', path: '/about' },
            { name: 'Contact', path: '/contact' },
          ].map((link) => (
            <Link 
              key={link.path}
              to={link.path} 
              className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}
            >
              {link.name}
              {isActive(link.path) && (
                <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full"></span>
              )}
            </Link>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition pr-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
          </Link>

          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[11px] font-black uppercase text-orange-600 italic">Salut, {user}</span>
              <button onClick={handleLogout} className="text-red-600 text-[10px] font-black uppercase hover:underline transition">Quitter</button>
            </div>
          ) : (
            <>
              <Link to="/register" className="text-gray-900 hover:text-orange-600 text-[11px] font-black uppercase tracking-widest transition">
                S'inscrire
              </Link>
              <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">
                Connexion
              </Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- LAYOUT ---
const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>
    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- REGISTER (Logic tzad f nefss style dyalk) ---
const Register = () => {
  const [formData, setFormData] = useState({ username: '', email: '', password: '' });
  const navigate = useNavigate();

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://127.0.0.1:8000/api/register/', formData);
      alert("✅ Bienvenue ! Compte créé avec succès.");
      navigate('/login');
    } catch (err) {
      alert("❌ Erreur d'inscription. Réessayez.");
    }
  };

  return (
    <PageLayout title="Créer un Compte">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <form className="space-y-6" onSubmit={handleRegister}>
          <input type="text" placeholder="NOM COMPLET" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold uppercase" onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="email" placeholder="EMAIL" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, email: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">S'inscrire Now</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- LOGIN (Style dyalk + Fix mochkil identifiers) ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      // T-akdi annaki f l-backend k-tqbli 'username' f blast 'email' f login view
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || formData.username.split('@')[0]);
      localStorage.setItem('token', res.data.token);
      alert("Bienvenue!");
      window.location.href = "/"; 
    } catch (err) {
      alert("Email or Password incorrect.");
    }
  };

  return (
    <PageLayout title="Connexion">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="text" placeholder="VOTRE EMAIL OU USERNAME" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Se Connecter</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- ABOUT (Kima kan 3ndek) ---
const About = () => (
  <PageLayout title="Notre Passion">
    <div className="max-w-5xl mx-auto space-y-12">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <h3 className="text-3xl font-black text-orange-600 italic mb-8 uppercase tracking-tighter text-center">Une Expérience Unique</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          <p className="text-white text-lg leading-relaxed font-medium italic opacity-90">
            Depuis notre lancement en 2026, **FastDélice** s'est donné pour mission de redéfinir la gastronomie rapide au Maroc. Nous croyons fermement que manger vite ne devrait jamais signifier manger mal. C'est pourquoi chaque plat qui sort de notre cuisine est traité avec le plus grand respect.
          </p>
          <p className="text-white text-lg leading-relaxed font-medium italic opacity-90">
            Notre secret ? Une équipe de chefs passionnés qui marient tradition et innovation. Nos pâtes à pizza reposent pendant 48 heures pour une légèreté incomparable. Chez FastDélice, chaque bouchée raconte une histoire d'excellence.
          </p>
        </div>
        <div className="mt-12 text-center text-white/70 italic text-sm">"La qualité n'est pas un acte, c'est une habitude."</div>
      </div>
    </div>
  </PageLayout>
);

// --- CONTACT (Kima kan 3ndek) ---
const Contact = () => (
  <PageLayout title="Contactez-Nous">
    <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-10">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-10 rounded-[3rem] shadow-2xl">
        <h3 className="text-2xl font-black text-orange-600 italic mb-6 uppercase">Coordonnées</h3>
        <div className="space-y-6 text-white">
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1">Adresse</p><p className="italic">123 Boulevard Gourmand, Casablanca</p></div>
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1">Téléphone</p><p className="italic">+212 522 12 34 56</p></div>
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1">Email</p><p className="italic">contact@fastdelice.ma</p></div>
        </div>
      </div>
      <form className="bg-black/40 backdrop-blur-xl border border-white/10 p-10 rounded-[3rem] space-y-4 shadow-2xl">
        <input type="text" placeholder="NOM" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition text-xs font-bold uppercase" />
        <textarea placeholder="MESSAGE" rows="4" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition text-xs font-bold uppercase"></textarea>
        <button className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Envoyer</button>
      </form>
    </div>
  </PageLayout>
);

// --- HOME (M3a ga3 les commentaires dyalk) ---
const Home = () => (
  <PageLayout>
    <div className="text-center py-16">
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">Fast<span className="text-orange-600">Délice</span></h1>
      <p className="text-xl text-white mb-12 font-black italic max-w-xl mx-auto opacity-90">"La passion du goût, l'élégance du service."</p>
      <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>

      <div className="mt-40 grid grid-cols-1 md:grid-cols-3 gap-8 text-center">
        {[{n: "YOUSSEF", t: "Meilleure pizza Margherita de la ville!"}, {n: "SANAA", t: "Service ultra rapide et emballage top."}, {n: "KARIM", t: "Les saveurs sont vraiment authentiques."}].map((v, i) => (
          <div key={i} className="bg-white/10 backdrop-blur-xl p-10 rounded-[3rem] border border-white/20 hover:bg-white/20 transition-all duration-500 shadow-xl">
             <div className="text-orange-500 mb-4 text-xs tracking-widest">★★★★★</div>
             <p className="text-white italic font-bold mb-6">"{v.t}"</p>
             <span className="text-[10px] font-black text-orange-500 uppercase tracking-widest">— {v.n}</span>
          </div>
        ))}
      </div>
    </div>
  </PageLayout>
);

// (Khalli l-baqi dyal Menu o Panier kima kano 3ndek exactly)

export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={/* Menu component dyalk */ null} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/panier" element={/* Panier component dyalk */ null} />
        </Routes>
      </div>
    </Router>
  );
}
